1. #Requires -Version 5.0
2. <#
3. .SYNOPSIS
4. Verify that the Windows runner setup matches documented requirements.
5. 
6. .DESCRIPTION
7. Scans the system for Rockwell software, SDKs, NuGet sources, and developer tools.
8. Reports what is installed and flags mismatches against expected versions.
9. 
10. Runs on PowerShell 5.1+ (including Core pwsh 7+).
11. 
12. .EXAMPLE
13. .\verify-setup.ps1
14. .\verify-setup.ps1 -Verbose
15. #>
16. 
17. param(
18.     [switch]$Verbose
19. )
20. 
21. $ErrorActionPreference = "Continue"
22. $script:issues = @()
23. $script:warnings = @()
24. 
25. function Test-Component {
26.     param(
27.         [string]$Name,
28.         [scriptblock]$Test,
29.         [string]$Expected = ""
30.     )
31.     
32.     $result = & $Test
33.     $pass = $result.Pass
34.     $detail = $result.Detail
35.     
36.     $status = if ($pass) { "[OK]" } else { "[!!]" }
37.     $color = if ($pass) { "Green" } else { "Red" }
38.     
39.     Write-Host "$status $Name" -ForegroundColor $color
40.     
41.     if (-not $pass) {
42.         $script:issues += $Name
43.     }
44.     
45.     if ($Expected) {
46.         Write-Host "  Expected: $Expected" -ForegroundColor Gray
47.     }
48.     if ($detail) {
49.         Write-Host "  $detail" -ForegroundColor Cyan
50.     }
51.     Write-Host ""
52. }
53. 
54. Write-Host "========================================" -ForegroundColor Cyan
55. Write-Host "WINDOWS RUNNER SETUP VERIFICATION" -ForegroundColor Cyan
56. Write-Host "========================================" -ForegroundColor Cyan
57. Write-Host ""
58. 
59. # ============ ROCKWELL SOFTWARE ============
60. Write-Host "1. ROCKWELL SOFTWARE" -ForegroundColor Yellow
61. Write-Host "==================" -ForegroundColor Yellow
62. 
63. # Studio 5000
64. Test-Component "Studio 5000 installed" {
65.     $path = Get-ChildItem "C:\RA\*-Studio5000-Web" -Directory -ErrorAction SilentlyContinue
66.     @{
67.         Pass = $path -ne $null
68.         Detail = if ($path) { "Found: $($path.Name)" } else { "Not found in C:\RA\" }
69.     }
70. }
71. 
72. # Echo
73. Test-Component "FactoryTalk Logix Echo installed" {
74.     $path = Get-ChildItem "C:\RA\*-FTLogixEcho-DVD" -Directory -ErrorAction SilentlyContinue
75.     @{
76.         Pass = $path -ne $null
77.         Detail = if ($path) { "Found: $($path.Name)" } else { "Not found in C:\RA\" }
78.     }
79. }
80. 
81. # ============ SDK PACKAGES ============
82. Write-Host "2. SDK PACKAGES" -ForegroundColor Yellow
83. Write-Host "===============" -ForegroundColor Yellow
84. 
85. $sdkLocations = @(
86.     @{ Name = "Studio 5000 LDSDK"; Path = "C:\Users\Public\Documents\Studio 5000\Logix Designer SDK\dotnet" },
87.     @{ Name = "FactoryTalk Logix Echo SDK"; Path = "C:\Users\Public\Documents\FactoryTalk Logix Echo\SDK\dotnet" }
88. )
89. 
90. foreach ($sdk in $sdkLocations) {
91.     Test-Component "$($sdk.Name) directory" {
92.         $exists = Test-Path $sdk.Path
93.         $packages = @()
94.         if ($exists) {
95.             $packages = @(Get-ChildItem $sdk.Path -Filter "*.nupkg" -ErrorAction SilentlyContinue)
96.         }
97.         @{
98.             Pass = $exists -and $packages.Count -gt 0
99.             Detail = if ($packages) { 
100.                 $packages | ForEach-Object { $_.Name } | Out-String
101.             } else { 
102.                 "No .nupkg files found" 
103.             }
104.         }
105.     }
106. }
107. 
108. # ============ NUGET SOURCES ============
109. Write-Host "3. NUGET SOURCES" -ForegroundColor Yellow
110. Write-Host "================" -ForegroundColor Yellow
111. 
112. Test-Component "RA-Echo-SDK source registered" {
113.     $sources = dotnet nuget list source 2>$null
114.     $found = $sources | Select-String "RA-Echo-SDK"
115.     @{
116.         Pass = $found -ne $null
117.         Detail = if ($found) { $found.Line.Trim() } else { "Run: dotnet nuget add source `"C:\Users\Public\Documents\FactoryTalk Logix Echo\SDK\dotnet`" -n RA-Echo-SDK" }
118.     }
119. }
120. 
121. Test-Component "RA-LDSDK source registered" {
122.     $sources = dotnet nuget list source 2>$null
123.     $found = $sources | Select-String "RA-LDSDK"
124.     @{
125.         Pass = $found -ne $null
126.         Detail = if ($found) { $found.Line.Trim() } else { "Run: dotnet nuget add source `"C:\Users\Public\Documents\Studio 5000\Logix Designer SDK\dotnet`" -n RA-LDSDK" }
127.     }
128. }
129. 
130. # ============ SDK VERSIONS ============
131. Write-Host "4. SDK VERSIONS (from .csproj)" -ForegroundColor Yellow
132. Write-Host "===============================" -ForegroundColor Yellow
133. 
134. $csprojPath = "tests\harness\LogixEchoHarness\LogixEchoHarness.csproj"
135. if (Test-Path $csprojPath) {
136.     $csproj = Get-Content $csprojPath -Raw
137.     
138.     # Extract version requirements using simpler regex
139.     $ldMatch = [regex]::Match($csproj, 'RockwellAutomation\.LogixDesigner\.CSClient.*?Version="([\d.]+)"')
140.     $echoMatch = [regex]::Match($csproj, 'RockwellAutomation\.FactoryTalkLogixEcho\.Api\.Client.*?Version="([\d.]+)"')
141.     
142.     $ldVersion = $ldMatch.Groups[1].Value
143.     $echoVersion = $echoMatch.Groups[1].Value
144.     
145.     Write-Host ".csproj expects:" -ForegroundColor Cyan
146.     Write-Host "  • RockwellAutomation.LogixDesigner.CSClient v$ldVersion"
147.     Write-Host "  • RockwellAutomation.FactoryTalkLogixEcho.Api.Client v$echoVersion"
148.     Write-Host ""
149.     
150.     # Find actual files
151.     $ldPath = "C:\Users\Public\Documents\Studio 5000\Logix Designer SDK\dotnet"
152.     $echoPath = "C:\Users\Public\Documents\FactoryTalk Logix Echo\SDK\dotnet"
153.     
154.     Write-Host "Installed packages:" -ForegroundColor Cyan
155.     
156.     if (Test-Path $ldPath) {
157.         Get-ChildItem $ldPath -Filter "*LogixDesigner*.nupkg" -ErrorAction SilentlyContinue | ForEach-Object {
158.             $vMatch = [regex]::Match($_.Name, '(\d+\.\d+\.\d+)')
159.             $installed = $vMatch.Groups[1].Value
160.             if (-not $installed) { $installed = "unknown" }
161.             $status = if ($installed -eq $ldVersion) { "OK" } else { "!!" }
162.             Write-Host "  [$status] $($_.Name)" -ForegroundColor $(if ($installed -eq $ldVersion) { "Green" } else { "Red" })
163.         }
164.     }
165.     
166.     if (Test-Path $echoPath) {
167.         Get-ChildItem $echoPath -Filter "*FactoryTalkLogixEcho*.nupkg" -ErrorAction SilentlyContinue | ForEach-Object {
168.             $vMatch = [regex]::Match($_.Name, '(\d+\.\d+\.\d+)')
169.             $installed = $vMatch.Groups[1].Value
170.             if (-not $installed) { $installed = "unknown" }
171.             $status = if ($installed -eq $echoVersion) { "OK" } else { "!!" }
172.             Write-Host "  [$status] $($_.Name)" -ForegroundColor $(if ($installed -eq $echoVersion) { "Green" } else { "Red" })
173.         }
174.     }
175. }
176. Write-Host ""
177. 
178. # ============ DEVELOPER TOOLS ============
179. Write-Host "5. DEVELOPER TOOLS" -ForegroundColor Yellow
180. Write-Host "==================" -ForegroundColor Yellow
181. 
182. Test-Component ".NET SDK 10.0+" {
183.     $version = dotnet --version
184.     $major = [int]($version -split "\." | Select-Object -First 1)
185.     @{
186.         Pass = $major -ge 10
187.         Detail = "Installed: $version"
188.     }
189. }
190. 
191. Test-Component "PowerShell 7+ (pwsh)" {
192.     $version = $PSVersionTable.PSVersion
193.     @{
194.         Pass = $version.Major -ge 7
195.         Detail = "Installed: v$($version.Major).$($version.Minor)"
196.     }
197. }
198. 
199. Test-Component "Python 3.11+" {
200.     try {
201.         $version = python --version 2>&1
202.         if ($version -match "Python (\d+\.\d+)") {
203.             $pyVersion = [version]$matches[1]
204.             @{
205.                 Pass = $pyVersion -ge [version]"3.11"
206.                 Detail = "Installed: $version"
207.             }
208.         } else {
209.             @{
210.                 Pass = $false
211.                 Detail = $version
212.             }
213.         }
214.     } catch {
215.         @{
216.             Pass = $false
217.             Detail = "Python not found in PATH. Install Python 3.11+ and add to PATH."
218.         }
219.     }
220. }
221. 
222. Test-Component "Git for Windows 2.44.0+" {
223.     $version = git --version 2>$null
224.     @{
225.         Pass = $version -ne $null
226.         Detail = if ($version) { $version } else { "Not found" }
227.     }
228. }
229. 
230. Test-Component "GitHub CLI (gh)" {
231.     $version = gh --version 2>$null
232.     @{
233.         Pass = $version -ne $null
234.         Detail = if ($version) { $version } else { "Not found (optional for local dev)" }
235.     }
236. }
237. 
238. # ============ GIT CONFIGURATION ============
239. Write-Host "6. GIT CONFIGURATION" -ForegroundColor Yellow
240. Write-Host "====================" -ForegroundColor Yellow
241. 
242. Test-Component "Git schannel TLS backend" {
243.     $sslBackend = git config --global http.sslBackend 2>$null
244.     @{
245.         Pass = $sslBackend -eq "schannel"
246.         Detail = "Current: $sslBackend (should be 'schannel')"
247.     }
248. }
249. 
250. # ============ WORKING DIRECTORIES ============
251. Write-Host "7. WORKING DIRECTORIES" -ForegroundColor Yellow
252. Write-Host "======================" -ForegroundColor Yellow
253. 
254. $workDirs = @(
255.     "C:\CI-Pipeline-Files",
256.     "C:\CD-Pipeline-Files",
257.     "C:\actions-runner",
258.     "C:\actions-work"
259. )
260. 
261. foreach ($dir in $workDirs) {
262.     Test-Component "$dir exists" {
263.         $exists = Test-Path $dir
264.         @{
265.             Pass = $exists
266.             Detail = if (-not $exists) { "Create with: New-Item -ItemType Directory -Force `"$dir`"" }
267.         }
268.     }
269. }
270. 
271. # ============ SUMMARY ============
272. Write-Host ""
273. Write-Host "========================================" -ForegroundColor Cyan
274. Write-Host "SUMMARY" -ForegroundColor Cyan
275. Write-Host "========================================" -ForegroundColor Cyan
276. 
277. if ($script:issues.Count -eq 0) {
278.     Write-Host "[OK] All checks passed!" -ForegroundColor Green
279.     exit 0
280. } else {
281.     Write-Host "[FAILED] $($script:issues.Count) issue(s) found:" -ForegroundColor Red
282.     $script:issues | ForEach-Object { Write-Host "  - $_" -ForegroundColor Red }
283.     Write-Host ""
284.     Write-Host "Review the messages above for remediation steps." -ForegroundColor Yellow
285.     exit 1
286. }
287.

